page_overview=f'''<div class="section-title"><div><div class="eyebrow">WORKSPACE / OVERVIEW</div><h1>Model command center</h1><p>A single control plane for every model, endpoint and request.</p></div><div class="title-actions"><button class="btn btn-quiet" onclick="go('providers')">＋ Add provider</button><button class="btn btn-primary" onclick="demoAction()">⟳ Discover models</button></div></div><div class="notice"><div class="notice-icon">◉</div><div><strong>Interactive design preview</strong><span>All metrics, model names and availability statuses are fictional examples. Live credentials are not connected.</span></div><span class="notice-tag">DEMO DATA</span></div><div class="metric-grid">{metric('Indexed models','09','Across sample gateways','⬡')}{metric('Verified ready','04','Example completion checks','✓')}{metric('Active providers','03','Four example key profiles','⌁')}{metric('Avg. response','565ms','Illustrative sampled latency','◷')}</div><div class="dashboard-layout"><div class="dashboard-primary"><section class="panel"><div class="panel-head"><div><h3>Request activity</h3><p>Illustrative request telemetry over time</p></div><span class="period"><span class="period-dot"></span> Last 30 days</span></div><div class="traffic-summary"><span class="hero-stat">1,284</span><span class="traffic-annotation">↗ Total events</span><div class="traffic-rate">98% example success rate</div></div><div class="preview-chart">{svg}</div></section><section class="panel"><div class="panel-head"><div><h3>Model readiness</h3><p>Latest model status, by credential</p></div><button class="inline-link" onclick="go('models')">View all models →</button></div><div class="readiness-meter"><span class="meter-ready" style="width:47%"></span><span class="meter-discovered" style="width:30%"></span><span class="meter-failed" style="width:23%"></span></div><div class="readiness-legend"><span><i class="legend-dot bg-ready"></i> Ready <strong>4</strong></span><span><i class="legend-dot bg-discovered"></i> Discovered <strong>3</strong></span><span><i class="legend-dot bg-failed"></i> Issues <strong>2</strong></span></div><div class="list-separator"></div>'''+''.join(f'<div class="ready-model-row"><span class="model-avatar">⬡</span><span class="ready-model-main"><strong>{m}</strong><small>{pr} · {k}</small></span>{status(s)}<span class="latency">{ms}</span></div>' for m,pr,k,s,ms in models[:4])+'''</section></div><div class="dashboard-side"><section class="panel"><div class="panel-head"><div><h3>Provider health</h3><p>Example gateway registry</p></div></div><div class="provider-health">'''+''.join(f'<div class="health-row"><div class="health-logo">⌁</div><div><strong>{n}</strong><small>{k} keys · {m} models</small></div><span class="health-arrow">↗</span></div>' for n,k,m in [('CarteThyia','2','4'),('9Router','1','3'),('Demo Gateway','1','2')])+'''</div><button class="panel-footer" onclick="go('providers')">Manage connections →</button></section><section class="panel"><div class="panel-head"><div><h3>Recent events</h3><p>Example request health</p></div></div><div class="event-stack">'''+''.join(f'<div class="mini-event"><div class="event-glyph {"event-ok" if i%3 else "event-error"}">{"✓" if i%3 else "×"}</div><div><strong>{t}</strong><small>{m}</small></div><span>{2+i*3}m ago</span></div>' for i,(t,m) in enumerate([('Model test','atlas/reasoning-pro'),('Chat completion','nova/sonnet-4'),('Model discovery','9Router'),('Rate limit','helios/coder-32b'),('Chat completion','meridian/flash')]))+'''</div><button class="panel-footer" onclick="go('telemetry')">Open telemetry →</button></section><div class="tip-card"><div class="tip-icon">⚡</div><strong>Discovery is not validation</strong><p><code>GET /models</code> only indexes a model. Completion probes confirm readiness and may use token credits.</p></div></div></div>'''
page_models=f'''<div class="section-title"><div><div class="eyebrow">REGISTRY / MODEL EXPLORER</div><h1>Model explorer</h1><p>Discover once. Validate individually. Route with confidence.</p></div><span class="registry-count">⬡ 9 sample routes</span></div><div class="toolbar"><label class="search-field">⌕ <input id="model-search" placeholder="Search model names and providers..." oninput="filterModels()"/><span>⌘ K</span></label><label class="select-wrap">Status <select id="status-filter" onchange="filterModels()"><option value="all">All</option><option value="ready">Ready</option><option value="failed">Failed</option><option value="rate_limited">Rate limited</option></select></label></div><section class="panel"><div class="table-scroll"><table class="data-table" id="model-table"><thead><tr><th>MODEL / ROUTE</th><th>PROVIDER</th><th>CREDENTIAL</th><th>STATUS</th><th>LATENCY</th><th>LAST CHECKED</th><th>ACTION</th></tr></thead><tbody>{rows}</tbody></table></div><div class="table-foot"><span>Sample routes only — no API verification occurred</span><span>▴ Ready is not inferred from discovery</span></div></section>'''
page_providers='<div class="section-title"><div><div class="eyebrow">CONNECTIONS / PROVIDERS</div><h1>Providers & credentials</h1><p>Manage your API gateways and private key profiles.</p></div><button class="btn btn-primary" onclick="demoAction()">＋ Add provider</button></div><div class="security-preview">♧ In the native app keys are encrypted by the OS credential manager; this preview stores no credentials.</div><div class="providers-grid">'+''.join(f'''<section class="panel provider-card"><div class="provider-card-top"><div class="provider-badge">⌁</div><div class="provider-head"><h3>{name}</h3><p>{count} fictional credentials shown</p></div></div><div class="endpoint"><span>BASE ENDPOINT</span><code>{url}</code></div><div class="provider-card-stats"><span><strong>{models_count}</strong> sample models</span><span>Checked 11m ago (demo)</span></div><div class="card-divider"></div><div class="keys-title"><h4>API credentials</h4><button onclick="demoAction()">＋ Add key</button></div><div class="key-entry"><span class="key-entry-icon">⚿</span><div><strong>Primary · sample only</strong><small>•••• DEMO</small></div></div><button class="btn btn-secondary wide" onclick="demoAction()">⟳ Discover models</button></section>''' for name,url,count,models_count in [('CarteThyia','https://cartethyia-production-682d.up.railway.app/v1',2,4),('9Router','https://9router-production-fc96.up.railway.app/v1',1,3)])+'</div>'
page_chat='''<div class="preview-chat"><div class="section-title"><div><div class="eyebrow">WORKSPACE / UNIFIED CHAT</div><h1>Chat workspace</h1><p>One chat experience, multiple provider routes.</p></div><span class="registry-count">DESIGN PREVIEW</span></div><div class="notice"><div class="notice-icon">H</div><div><strong>Real chat requires desktop</strong><span>This offline preview demonstrates conversation layout only. It never sends model requests.</span></div></div><div id="demo-chat-messages"><div class="preview-only-chat">How do you design a fast and reliable Rust API router?</div><div class="preview-only-chat reply">Use asynchronous I/O with Tokio and reqwest, avoid leaking API keys to the frontend, and record per-route latencies. Validate the actual route rather than assuming that model discovery proves availability.</div></div><textarea id="demo-chat-text" rows="4" placeholder="Try a message in this interactive preview..."></textarea><button class="btn btn-primary" onclick="sendPreview()">↗ Send preview message</button></div>'''
page_telemetry=f'<div class="section-title"><div><div class="eyebrow">OBSERVABILITY / TELEMETRY</div><h1>Telemetry</h1><p>Health, errors and performance signals without external analytics.</p></div><span class="registry-count">DEMO / SAMPLE</span></div><div class="metric-grid">{metric("Total events","1,284","Fictional request counts","↗")}{metric("Failed events","24","Example anomalies","!")}{metric("Success rate","98%","Example conversion","✓")}{metric("Avg. latency","565ms","Measured in sample data","◷")}</div><section class="panel"><div class="panel-head"><div><h3>Request volume</h3><p>Illustrative history over 30 days</p></div></div><div class="preview-chart">{svg}</div></section>'
page_settings='''<div class="section-title"><div><div class="eyebrow">PREFERENCES / SETTINGS</div><h1>Workspace settings</h1><p>Appearance and behavior for your local control room.</p></div></div><section class="panel settings-wrap"><div class="panel-head"><div><h3>Appearance</h3><p>Hanoman signature Graphite Dark</p></div></div><div class="setting-row"><div><strong>Compact density</strong><p>Reduce row spacing in tables.</p></div><button class="preview-btn" onclick="document.body.classList.toggle('compact-density')">Toggle density</button></div><div class="setting-row"><div><strong>Interface accent</strong><p>Terracotta on Graphite</p></div><span class="mini-chip">● Graphite / Terracotta</span></div><div class="setting-row"><div><strong>Runtime status</strong><p>Static HTML preview, no network integrations.</p></div><span class="preview-only">OFFLINE</span></div></section>'''
nav=[('overview','◫','Overview'),('models','⬡','Model explorer'),('chat','☰','Chat workspace'),('providers','⌁','Providers & keys'),('telemetry','⌁','Telemetry'),('settings','⚙','Settings')]
html=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1.0"/><title>Hanoman Telemetri — Offline Interactive Preview</title><style>{css}</style></head><body><div class="app-shell"><aside class="sidebar"><div class="brand"><span class="h-mark"><span>H</span></span><div><strong>HANOMAN<span class="brand-caret">/</span></strong><small>TELEMETRI</small></div></div><div class="sidebar-group-label">WORKSPACE</div><nav class="preview-navigation sidebar-nav">'''+''.join(f'<button class="tab {"active" if i==0 else ""}" data-tab="{page}" onclick="go(\'{page}\')"><span class="sym">{ic}</span><span>{title}</span></button>' for i,(page,ic,title) in enumerate(nav[:3]))+'''</nav><div class="sidebar-group-label sidebar-connectors">INFRASTRUCTURE</div><nav class="preview-navigation sidebar-nav">'''+''.join(f'<button class="tab" data-tab="{page}" onclick="go(\'{page}\')"><span class="sym">{ic}</span><span>{title}</span></button>' for page,ic,title in nav[3:5])+'''</nav><div class="sidebar-spacer"></div><button class="sidebar-setting" onclick="go('settings')">⚙ &nbsp; Settings</button><div class="sidebar-system"><span class="system-led"></span><div><strong>Preview environment</strong><small>Fictional sample data</small></div></div><div class="sidebar-version">v0.1.0 · OFFLINE PREVIEW</div></aside><div class="app-content"><header class="topbar"><div class="breadcrumbs"><span>Workspace</span><span>›</span><strong id="breadcrumb">Overview</strong></div><div class="topbar-right"><span class="preview-only">DEMO DATA</span><div class="topbar-divider"></div><span class="topbar-account"><span class="account-icon">H</span>Local workspace</span></div></header><main class="page-content">'''+''.join(f'<div class="preview-page {"active" if name=="overview" else ""}" id="page-{name}">{content}</div>' for name,content in [('overview',page_overview),('models',page_models),('chat',page_chat),('providers',page_providers),('telemetry',page_telemetry),('settings',page_settings)])+'''</main></div></div><div class="toast" id="demo-toast" style="display:none"><span id="demo-toast-text"></span><button onclick="document.getElementById('demo-toast').style.display='none'">×</button></div><script>
const titles={overview:'Overview',models:'Model explorer',chat:'Chat workspace',providers:'Providers & keys',telemetry:'Telemetry',settings:'Settings'};
function go(name){document.querySelectorAll('.preview-page').forEach(x=>x.classList.toggle('active',x.id==='page-'+name));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.getElementById('breadcrumb').textContent=titles[name];scrollTo(0,0)}
function demoAction(){const t=document.getElementById('demo-toast');document.getElementById('demo-toast-text').textContent='Design preview only. Launch the native desktop application for real API discovery, credential management and chat.';t.style.display='flex';setTimeout(()=>t.style.display='none',6000)}
function filterModels(){const search=document.getElementById('model-search').value.toLowerCase();const status=document.getElementById('status-filter').value;document.querySelectorAll('#model-table tbody tr').forEach(r=>{r.style.display=(r.innerText.toLowerCase().includes(search)&&(status==='all'||r.querySelector('.status-pill').classList.contains('s-'+status)))?'':'none'})}
function sendPreview(){const t=document.getElementById('demo-chat-text');if(!t.value.trim())return;const m=document.getElementById('demo-chat-messages');const p=document.createElement('div');p.className='preview-only-chat';p.textContent=t.value;m.appendChild(p);const n=document.createElement('div');n.className='preview-only-chat reply';n.textContent='This is a static UI preview. No network request was sent and no AI model responded.';m.appendChild(n);t.value='';n.scrollIntoView({behavior:'smooth',block:'nearest'});}
</script></body></html>'''
(p/'preview.html').write_text(html)
print('Created preview:', (p/'preview.html').stat().st_size,'bytes')
